import { defineComponent, ref } from 'vue';

// Create a Vue component named ControlledInputExample with a setup function
export default defineComponent({
  name: 'ControlledInputExample',
  setup() {
    // Initialize inputValue ref here
    const inputValue = ref('');

    // Define handleInput function here
    const handleInput = (event) => {
      inputValue.value = event.target.value;
    };

    return { inputValue, handleInput };
  },
  template: `
    <div>
      <!-- Add text input here -->
      <input :value="inputValue" @input="handleInput" />

      <!-- Add paragraph to display input value here -->
    </div>
  `
});
